function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 100000) return 'grid needs 1 to 10^5 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 100000) return 'Each row needs 1 to 10^5 cells.';
  if (grid.length * n < 2 || grid.length * n > 100000) return 'grid has 2 to 10^5 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value is an integer from 1 to 10^5.';
  }
  return null;
}

