function canPartitionGrid(grid) {
  let total = 0;
  for (const row of grid) {
    for (const value of row) total += value;
  }

  function check(matrix) {
    const rows = matrix.length;
    const cols = matrix[0].length;
    const seen = new Set();
    let topSum = 0;
    for (let k = 1; k < rows; k++) {
      for (const value of matrix[k - 1]) {
        topSum += value;
        seen.add(value);
      }
      const diff = topSum - (total - topSum);
      if (diff === 0) return true;
      if (diff < 0) continue;
      if (k > 1 && cols > 1 && seen.has(diff)) return true;
      if (cols === 1 && (matrix[0][0] === diff || matrix[k - 1][0] === diff)) return true;
      if (k === 1 && (matrix[0][0] === diff || matrix[0][cols - 1] === diff)) return true;
    }
    return false;
  }

  const transposed = grid[0].map((_, c) => grid.map(row => row[c]));
  return check(grid) || check([...grid].reverse()) || check(transposed) || check([...transposed].reverse());
}

