function canPartitionGrid(grid) {
  const m = grid.length, n = grid[0].length;
  // Whether the given cells form one 4-connected piece (found by a flood fill from the first cell).
  const connected = cells => {
    if (cells.length === 0) return false;
    const inside = new Set(cells.map(([r, c]) => r * n + c));
    const reached = new Set([cells[0][0] * n + cells[0][1]]), todo = [cells[0]];
    while (todo.length) {
      const [r, c] = todo.pop();
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const key = (r + dr) * n + (c + dc);
        if (r + dr < 0 || r + dr >= m || c + dc < 0 || c + dc >= n || !inside.has(key) || reached.has(key)) continue;
        reached.add(key);
        todo.push([r + dr, c + dc]);
      }
    }
    return reached.size === inside.size;
  };
  const sum = cells => cells.reduce((s, [r, c]) => s + grid[r][c], 0);
  const cuts = [];
  for (let k = 1; k < m; k++) cuts.push((r, c) => r < k);
  for (let k = 1; k < n; k++) cuts.push((r, c) => c < k);
  for (const inFirst of cuts) {
    const first = [], second = [];
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) (inFirst(r, c) ? first : second).push([r, c]);
    if (sum(first) === sum(second)) return true;
    // Try leaving out each cell of either part, then check the sums and that part's connectivity.
    for (const [part, other] of [[first, second], [second, first]]) {
      for (let i = 0; i < part.length; i++) {
        const rest = part.filter((_, j) => j !== i);
        if (sum(rest) === sum(other) && connected(rest)) return true;
      }
    }
  }
  return false;
}

