function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const shape = rand();
  let m, n;
  if (shape < 0.2) { m = 1; n = large ? int(60, 100) : int(2, 6); }
  else if (shape < 0.4) { m = large ? int(60, 100) : int(2, 6); n = 1; }
  else { m = large ? int(40, 100) : int(1, 4); n = large ? int(40, 100) : int(2, 4); }
  const limit = 100000, top = large ? (rand() < 0.5 ? limit : int(2, 60)) : int(1, 6);
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => int(1, top)));
  const mode = rand();
  if (mode < 0.3) return [grid];
  // Pick a cut, then shift values so that the parts balance exactly or after leaving out one chosen cell.
  const horizontal = m > 1 && (n === 1 || rand() < 0.5);
  const k = horizontal ? int(1, m - 1) : int(1, n - 1);
  const first = [], second = [];
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) ((horizontal ? r < k : c < k) ? first : second).push([r, c]);
  const [big, small] = rand() < 0.5 ? [first, second] : [second, first];
  const skip = mode < 0.55 ? null : big[int(0, big.length - 1)];
  const removed = skip ? grid[skip[0]][skip[1]] : 0;
  const sum = cells => cells.reduce((s, [r, c]) => s + grid[r][c], 0);
  // Moves the part's total by up to delta, keeping every value in [1, limit] and the chosen cell unchanged.
  const shift = (part, delta) => {
    const start = int(0, part.length - 1);
    for (let t = 0; t < part.length && delta !== 0; t++) {
      const [r, c] = part[(start + t) % part.length];
      if (skip && r === skip[0] && c === skip[1]) continue;
      const step = delta > 0 ? Math.min(delta, limit - grid[r][c]) : Math.max(delta, 1 - grid[r][c]);
      grid[r][c] += step;
      delta -= step;
    }
    return delta;
  };
  const gap = sum(big) - removed - sum(small);
  if (gap > 0) shift(big, -shift(small, gap));
  else if (gap < 0) shift(small, shift(big, -gap));
  return [grid];
}
